class Solution:
    def sumHighestAndLowestFrequency(self, nums):
        hashmap = dict(Counter(nums))
        highest_freq, lowest_freq = 0, float('inf')

        for value in hashmap.values():
            if value >= highest_freq:
                highest_freq = value

        for value in hashmap.values():
